public function test_avatar_second_upload_same_filename_succeeds(): void
{
    Storage::fake('public');

    $teacher = User::create([
        'LoginName' => 'avatar-twice@example.com',
        'Name' => 'Avatar Twice',
        'PSW' => password_hash('secret-123', PASSWORD_DEFAULT),
        'type' => 'T',
