    ]);
    $token = $this->issueToken($teacher->id);

    $headers = [
        'Authorization' => "Bearer {$token}",
        'Accept' => 'application/json',
    ];

    $this->withHeaders($headers)->post('/api/v1/me/avatar', [
        'avatar' => UploadedFile::fake()->image('avatar.jpg', 80, 80),
    ])->assertOk();

